-- Show authorized related history without moving or duplicating source activities.
CREATE OR REPLACE FUNCTION public.get_timeline_activity_page(p_entity_kind text, p_entity_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_categories text[] DEFAULT NULL::text[], p_assignees uuid[] DEFAULT NULL::uuid[], p_include_unassigned boolean DEFAULT false, p_search text DEFAULT NULL::text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_page_size integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$ DECLARE v_limit integer := LEAST(GREATEST(COALESCE(p_page_size,40),1),100); v_result jsonb; v_workspace uuid; v_contacts uuid[] := ARRAY[]::uuid[]; v_company uuid; BEGIN
 IF p_entity_kind='deal' THEN
 SELECT d.workspace_id,d.company_id,array_remove(ARRAY[d.primary_contact_id] || ARRAY(SELECT dc.contact_id FROM public.deal_contacts dc WHERE dc.deal_id=d.id),NULL) INTO v_workspace,v_company,v_contacts FROM public.shared_fields_deals d WHERE d.id=p_entity_id;
 END IF; IF p_entity_kind NOT IN ('lead','contact','company','deal','ticket') THEN RAISE EXCEPTION 'invalid entity kind'; END IF; IF (p_cursor_at IS NULL) <> (p_cursor_id IS NULL) THEN RAISE EXCEPTION 'cursor timestamp and id must be provided together'; END IF; WITH scoped AS MATERIALIZED (SELECT a.id,a.owner_id,a.type,a.subject,a.body,a.due_date,a.completed,a.related_lead_id,a.related_contact_id,a.related_company_id,a.related_deal_id,a.created_at,a.updated_at,a.outcome,a.outcome_set_at,a.external_ids,a.duration_ms,a.disposition,a.recording_url,a.meeting_outcome,a.meeting_location,a.task_status,a.task_priority,a.email_direction,a.email_status,a.hubspot_owner_id,a.hs_object_id,a.hs_createdate,a.hs_lastmodifieddate,a.mentions,a.attachments,a.relink_checked_at,a.workspace_id,a.deleted_at,a.created_by,a.recording_sid,a.recording_duration_seconds,a.recording_channels,a.transcription,a.transcription_status,a.transcription_model,a.related_ticket_id,a.custom_fields,a.meeting_key,a.remind_before_minutes,a.reminder_sent_at,a.assigned_to,a.activity_date,a.task_type,a.recurrence,a.recurrence_parent_id,a.contacted_contact_ids,a.pinned_at,a.follow_up_of,CASE WHEN p_entity_kind='deal' AND a.related_deal_id IS DISTINCT FROM p_entity_id THEN CASE WHEN a.related_contact_id=ANY(v_contacts) THEN 'contact' ELSE 'company' END ELSE NULL END AS timeline_related_via,COALESCE(a.hs_createdate,a.created_at) effective_at,CASE WHEN a.type IN ('call','email','whatsapp','task','meeting','survey') THEN a.type::text WHEN a.type IN ('sms','linkedin_message','postal_mail') THEN 'message' ELSE 'note' END category FROM public.activities a WHERE a.deleted_at IS NULL AND CASE p_entity_kind WHEN 'lead' THEN a.related_lead_id=p_entity_id WHEN 'contact' THEN a.related_contact_id=p_entity_id WHEN 'company' THEN a.related_company_id=p_entity_id WHEN 'deal' THEN a.workspace_id=v_workspace AND (a.related_deal_id=p_entity_id OR a.related_contact_id=ANY(v_contacts) OR a.related_company_id=v_company) WHEN 'ticket' THEN a.related_ticket_id=p_entity_id ELSE false END AND (p_since IS NULL OR COALESCE(a.hs_createdate,a.created_at)>=p_since) AND (p_until IS NULL OR COALESCE(a.hs_createdate,a.created_at)<p_until) AND (p_categories IS NULL OR cardinality(p_categories)=0 OR CASE WHEN a.type IN ('call','email','whatsapp','task','meeting','survey') THEN a.type::text WHEN a.type IN ('sms','linkedin_message','postal_mail') THEN 'message' ELSE 'note' END=ANY(p_categories)) AND ((COALESCE(cardinality(p_assignees),0)=0 AND NOT COALESCE(p_include_unassigned,false)) OR (COALESCE(cardinality(p_assignees),0)>0 AND COALESCE(a.assigned_to,a.owner_id)=ANY(p_assignees)) OR (COALESCE(p_include_unassigned,false) AND COALESCE(a.assigned_to,a.owner_id) IS NULL)) AND (NULLIF(btrim(p_search),'') IS NULL OR concat_ws(' ',a.subject,a.body) ILIKE '%'||p_search||'%' OR EXISTS (SELECT 1 FROM public.email_messages em WHERE em.id=CASE WHEN (a.external_ids->>'email_message_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (a.external_ids->>'email_message_id')::uuid ELSE NULL END AND concat_ws(' ',em.from_name,em.from_email,em.subject,em.body_text,em.body_html) ILIKE '%'||p_search||'%'))), counts AS (SELECT COALESCE(sum(n),0)::bigint total,COALESCE(jsonb_object_agg(category,n),'{}'::jsonb) categories FROM (SELECT category,count(*)::bigint n FROM scoped GROUP BY category)c), page_plus AS (SELECT * FROM scoped WHERE p_cursor_at IS NULL OR (effective_at,id)<(p_cursor_at,p_cursor_id) ORDER BY effective_at DESC,id DESC LIMIT v_limit+1), page AS (SELECT * FROM page_plus ORDER BY effective_at DESC,id DESC LIMIT v_limit), tail AS (SELECT effective_at,id FROM page ORDER BY effective_at ASC,id ASC LIMIT 1) SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'effective_at'-'category' ORDER BY effective_at DESC,id DESC) FROM page p),'[]'::jsonb),'total',COALESCE((SELECT total FROM counts),0),'counts',COALESCE((SELECT categories FROM counts),'{}'::jsonb),'has_more',(SELECT count(*)>v_limit FROM page_plus),'next_at',CASE WHEN (SELECT count(*)>v_limit FROM page_plus) THEN (SELECT effective_at FROM tail) ELSE NULL END,'next_id',CASE WHEN (SELECT count(*)>v_limit FROM page_plus) THEN (SELECT id FROM tail) ELSE NULL END) INTO v_result; RETURN v_result; END; $function$
;
